from pathlib import Path
import hashlib,heapq,json,random
p=Path(__file__).resolve().parent;(p/'inputs').mkdir(exist_ok=True);cases=[]
def put(id,name,n,edges,sample=None):
 text=f'{n} {len(edges)}\n'+''.join(f'{u+1} {v+1}\n' for u,v in edges)
 g=[[] for _ in range(n)]
 for u,v in edges:g[u].append(v)
 if id=='topological_lexicographical':
  degree=[0]*n
  for _,v in edges:degree[v]+=1
  ready=[v for v in range(n) if degree[v]==0];heapq.heapify(ready);answer=[]
  while ready:
   u=heapq.heappop(ready);answer.append(u+1)
   for v in g[u]:
    degree[v]-=1
    if degree[v]==0:heapq.heappush(ready,v)
  expected=' '.join(map(str,answer))+'\n' if len(answer)==n else '-1\n'
 else:
  # Iterative postorder DP, independent of returned topological sort.
  length=[0]*n;state=[0]*n
  for v in range(n):
   if state[v]:continue
   stack=[(v,False)]
   while stack:
    u,done=stack.pop()
    if done:
     length[u]=max((length[w]+1 for w in g[u]),default=0);state[u]=2
    elif state[u]==0:
     state[u]=1;stack.append((u,True))
     for w in g[u]:
      if state[w]==0:stack.append((w,False))
      elif state[w]==1:raise ValueError('cyclic DP input')
  expected=str(max(length,default=0))+'\n'
 if sample is not None:assert expected==sample
 f=p/'inputs'/f'{id}_{name}.in';f.write_text(text);o=f.with_suffix('.out');o.write_text(expected)
 cases.append({'id':id,'case':name,'input':str(f),'expected':str(o),'n':n,'m':len(edges),'kind':'official_sample' if sample is not None else 'custom_problem_domain','input_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'output_sha256':hashlib.sha256(o.read_bytes()).hexdigest()})
put('topological_lexicographical','sample1',4,[(1,0),(2,3),(1,3)],'2 1 3 4\n');put('topological_lexicographical','sample2',2,[(0,1),(0,1),(1,0)],'-1\n')
put('topological','sample1',4,[(0,1),(0,2),(2,1),(1,3),(2,3)],'3\n');put('topological','sample2',6,[(1,2),(3,4),(4,5)],'2\n');put('topological','sample3',5,[(4,2),(1,2),(1,3),(4,1),(4,0),(0,3),(3,2),(0,2)],'3\n')
for id,n in [('topological_lexicographical',200000),('topological',100000)]:
 rng=random.Random(0x842366)
 put(id,'single_edge',n,[(n-1,0)])
 put(id,'forward_chain',n,[(i-1,i) for i in range(1,n)])
 put(id,'reverse_chain',n,[(i,i-1) for i in range(1,n)])
 put(id,'star',n,[(0,i) for i in range(1,n)])
 put(id,'reverse_star',n,[(i,0) for i in range(1,n)])
 perm=list(range(n));rng.shuffle(perm)
 for kind in ['random_dag','permuted_dag']:
  pairs=set()
  while len(pairs)<n:
   a=rng.randrange(n-1);b=rng.randrange(a+1,n)
   pairs.add((a,b) if kind=='random_dag' else (perm[a],perm[b]))
  es=list(pairs);rng.shuffle(es);put(id,kind,n,es)
 if id.endswith('lexicographical'):put(id,'cycle',n,[(i,(i+1)%n) for i in range(n)])
(p/'inputs.json').write_text(json.dumps(cases,indent=2)+'\n');print(len(cases),'inputs ready')

