#include <chrono>
#include <cstdint>
#include <iostream>
#include <random>
#include <string>
#include HEADER
int main(int argc,char**argv){
 const int kind=std::stoi(argv[1]), n=std::stoi(argv[2]), repeats=std::stoi(argv[3]);
 std::mt19937 rng(0x91AB11); Graph g(n);
 if(kind==1)for(int i=1;i<n;++i)g[i-1].push_back(i);
 if(kind==2)for(int i=n-1;i>0;--i)g[i].push_back(i-1);
 if(kind==3)for(int i=1;i<n;++i)g[0].push_back(i);
 if(kind==4)for(int i=1;i<n;++i)g[i].push_back(0);
 if(kind==5)for(int i=1;i<n;++i)for(int j=1;j<=8;++j)if(i>=j)g[i-j].push_back(i);
 if(kind==6)for(int i=1;i<n;++i)for(int j=0;j<4;++j)g[rng()%i].push_back(i);
 if(kind==7){std::vector<int> perm(n);for(int i=0;i<n;++i)perm[i]=i;std::shuffle(perm.begin(),perm.end(),rng);for(int i=1;i<n;++i)for(int j=0;j<4;++j)g[perm[rng()%i]].push_back(perm[i]);}
 if(kind==8)for(int i=0;i<n;++i)g[i].push_back((i+1)%n);
 std::uint64_t checksum=0;const auto begin=std::chrono::steady_clock::now();
 for(int rep=0;rep<repeats;++rep){auto out=TopologicalSortLexicographical(g);checksum+=out.size();if(!out.empty())checksum+=static_cast<std::uint64_t>(out[n/2]);}
 const auto end=std::chrono::steady_clock::now();std::cout<<std::chrono::duration<double,std::milli>(end-begin).count()<<' '<<checksum<<'\n';(void)argc;
}

