        if (n > 64) { offsets[levels++] = total; ++total; }
        std::vector<std::uint64_t> bits(total);
        std::size_t ready_count = 0;
        int minimum = -1;
        const auto insert = [&](int vertex) {
            if (minimum < 0 || vertex < minimum) minimum = vertex;
            ++ready_count;
            std::size_t index = static_cast<std::size_t>(vertex);
            for (std::size_t level = 0; level < levels; ++level) {
                auto& word = bits[offsets[level] + (index >> 6)];
